VAR
    hasPrev : BOOL := FALSE;
    prevMode : INT := 0;
    prevReset : BOOL := FALSE;
    prevFlowSP : REAL := 0.0;
    prevValveCommand : REAL := 0.0;
    prevET : REAL := 0.0;
    prevEF : REAL := 0.0;
    resetRising : BOOL;
    eT : REAL;
    eF : REAL;
    flowRaw : REAL;
    valveRaw : REAL;
    trialT : REAL;
    trialF : REAL;
END_VAR

fault := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);
resetRising := resetBtn AND NOT prevReset;

IF NOT hasPrev THEN
    normalMode := FALSE;
    flowSP := manualFlowSP;
    valveCommand := manualValve;
ELSIF resetRising THEN
    normalMode := FALSE;
    flowSP := manualFlowSP;
    valveCommand := manualValve;
ELSIF fault THEN
    normalMode := FALSE;
    flowSP := manualFlowSP;
    valveCommand := manualValve;
ELSIF mode <> prevMode THEN
    normalMode := FALSE;
    IF mode = 2 THEN
        flowSP := prevFlowSP;
        valveCommand := prevValveCommand;
    ELSE
        flowSP := manualFlowSP;
        valveCommand := prevValveCommand;
    END_IF;
ELSE
    normalMode := TRUE;
    IF mode = 0 THEN
        flowSP := manualFlowSP;
        valveCommand := manualValve;
    ELSIF mode = 1 THEN
        flowSP := manualFlowSP;
        eF := flowSP - flowPV;
